using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps;using MapSharedProps.EditorTools;using MapTunnels.EditorTools;
public static class Cobweb177Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));public static string Out=Path.Combine(Root,"Evidence177");static string Input=>Path.Combine(Root,"Input177");const string Folder="Assets/Imported177-valid";
