 static Camera Cam(){var c=new GameObject("背景撮影").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.02f,.025f,.03f);c.fieldOfView=45;c.nearClipPlane=.03f;return c;}
 static GameObject Web(Vector3 p,Quaternion q,Transform parent=null){var o=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/small-mine_cobweb.prefab"));o.transform.SetParent(parent,false);o.transform.SetPositionAndRotation(p,q);return o;}
 static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.03f,.035f,.04f);}
 public static void Run(){Directory.CreateDirectory(Out);try{
  Empty();var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
  if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder("Assets","Imported177-valid");var data=SmallPropsV1.Read(Path.Combine(Input,"small_props.json"));Check(data.mineCobwebV1!=null,"formal optional accepted");var root=new GameObject("巣の正式生成");var prefabs=new Dictionary<string,GameObject>();SmallPropsV1.Build(Input,Folder,root.transform,Shader.Find("MapSharedProps/Lit"),prefabs);Check(prefabs.Count==53,"53 small including new web");int old=0;foreach(var kv in prefabs.Where(p=>p.Key!="mine_cobweb")){var previous=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported164-valid/small-"+kv.Key+".prefab");Check(previous,"previous52 exists "+kv.Key);Check(ColliderSnapshot109.MeshHash(previous.GetComponent<MeshFilter>().sharedMesh)==ColliderSnapshot109.MeshHash(kv.Value.GetComponent<MeshFilter>().sharedMesh),"old mesh "+kv.Key);if(previous.GetComponentsInChildren<Collider>().Length>0)Check(ColliderSnapshot109.Capture(previous)==ColliderSnapshot109.Capture(kv.Value),"old collider "+kv.Key);else Check(kv.Value.GetComponentsInChildren<Collider>().Length==0,"old noncollider "+kv.Key);old++;}Check(old==52,"previous52");
  var web=prefabs["mine_cobweb"];var mesh=web.GetComponent<MeshFilter>().sharedMesh;var material=web.GetComponent<Renderer>().sharedMaterial;Check(mesh.triangles.Length/3==80,"bounded triangles");Check(web.GetComponentsInChildren<Collider>().Length==0&&web.GetComponentsInChildren<Light>().Length==0,"default decorative");Check(material.IsKeywordEnabled("_ALPHATEST_ON")&&!material.IsKeywordEnabled("_EMISSION")&&material.renderQueue==2450,"clipped nonemissive");Check(web.GetComponent<Renderer>().shadowCastingMode==ShadowCastingMode.Off,"no opaque quad shadow");var tex=(Texture2D)material.GetTexture("_BaseMap");Check(tex&&tex.width==512&&tex.mipmapCount>1,"texture");
  var saved=PrefabUtility.SaveAsPrefabAsset(root,Folder+"/placed.prefab");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(saved);var instance=root.GetComponentInChildren<MeshFilter>();Check(instance&&instance.sharedMesh==mesh&&instance.GetComponent<Renderer>().sharedMaterial==material,"save destroy reinstantiate references");EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),Folder+"/reload.unity");Empty();EditorSceneManager.OpenScene(Folder+"/reload.unity");Check(UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Any(x=>x.sharedMaterial==material&&x.sharedMaterial.IsKeywordEnabled("_ALPHATEST_ON")),"scene reloaded clipped texture");
  var raw=File.ReadAllText(Path.Combine(Input,"small_props.json"));var cases=new List<string>();foreach(var tag in new[]{"missing","version","png","index","nan","nonSolid","circle","shape"}){var d=JsonUtility.FromJson<SmallPropsV1.Data>(raw);if(tag=="missing")d.mineCobwebV1=null;else if(tag=="version")d.mineCobwebV1.version=999;else if(tag=="png")d.mineCobwebV1.textures.colour="bad";else if(tag=="index")d.mineCobwebV1.assets[0].triangles[0]=99999;else if(tag=="nan")d.mineCobwebV1.assets[0].positions[0]=float.NaN;else if(tag=="circle"||tag=="shape"){var a=d.mineCobwebV1.assets[0];a.radius=.25f;a.height=.8f;a.shape=tag=="shape";a.circleColliders=new[]{new SmallPropsV1.CircleProxy{center=new[]{0f,0f,0f},radius=.25f,height=.8f}};}bool valid=tag=="nonSolid"||tag=="circle"||tag=="shape";d.mineCobwebV1=MineCobwebV1.Optional(d.mineCobwebV1);Check((d.mineCobwebV1!=null)==valid,"optional "+tag);string folder="Assets/Imported177-"+tag;if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets","Imported177-"+tag);var temp=new GameObject(tag);var p=new Dictionary<string,GameObject>();if(valid){MineCobwebV1.Build(Input,folder,temp.transform,p,d);var o=(GameObject)PrefabUtility.InstantiatePrefab(p["mine_cobweb"]);var co=o.GetComponent<MeshCollider>();if(tag=="nonSolid")Check(!co,"no collider");else if(tag=="shape")Check(co.sharedMesh==o.GetComponent<MeshFilter>().sharedMesh,"shape exact");else Check(Vector3.Distance(co.sharedMesh.bounds.size,new Vector3(.5f,.8f,.5f))<1e-5,"circle bounds");UnityEngine.Object.DestroyImmediate(o);}UnityEngine.Object.DestroyImmediate(temp);cases.Add(tag);}
