  string bad=Path.Combine(Root,"Input177-invalid");Directory.CreateDirectory(bad);File.WriteAllText(Path.Combine(bad,"small_props.json"),raw.Replace("\"mineCobwebV1\":{\"version\":1","\"mineCobwebV1\":{\"version\":999"));File.Copy(Path.Combine(Input,"props.csv"),Path.Combine(bad,"props.csv"),true);Empty();root=new GameObject("不正拡張fallback");prefabs=new Dictionary<string,GameObject>();SmallPropsV1.Build(bad,"Assets/Imported177-version",root.transform,Shader.Find("MapSharedProps/Lit"),prefabs);Check(prefabs.Count==52&&!prefabs.ContainsKey("mine_cobweb"),"invalid retains52 real prefabs");UnityEngine.Object.DestroyImmediate(root);
  Empty();var full=MapSharedPropsBuilder.Build(Path.Combine(Root,"Input177-mixed"));Check(full.prefabs.Count==73&&full.prefabs.Keys.Count(k=>k.StartsWith("cnd"))==20,"formal73 with cave20 actual="+full.prefabs.Count);UnityEngine.Object.DestroyImmediate(full.root);
